import { renderContactStrip } from './solution';

function equal(actual: unknown, expected: unknown, message: string): void {
  if (!Object.is(actual, expected)) throw new Error(`${message}: expected ${String(expected)}, got ${String(actual)}`);
}
function throwsType(fn: () => unknown, message: string): void {
  try { fn(); } catch (error) {
    if (error instanceof TypeError) return;
    throw new Error(`${message}: wrong error type`);
  }
  throw new Error(`${message}: did not throw`);
}

equal(renderContactStrip('People', []), '<nav aria-label="CONTACTS"><h1>People</h1><ul></ul></nav>', 'empty contacts');

const contacts = [
  { label: 'Email & alerts', address: 'mailto:a@example.test?x=1&y="two"', glyph: '<mail>' },
  { label: "Dev's page", address: '/dev/<id>', glyph: 'D&G' },
];
const before = JSON.stringify(contacts);
const rendered = renderContactStrip('A < B & "C" \'D\'', contacts);
const expected = '<nav aria-label="CONTACTS"><h1>A &lt; B &amp; &quot;C&quot; &#39;D&#39;</h1><ul>'
  + '<li><a href="mailto:a@example.test?x=1&amp;y=&quot;two&quot;" aria-label="Email &amp; alerts"><span>&lt;mail&gt;</span></a></li>'
  + '<li><a href="/dev/&lt;id&gt;" aria-label="Dev&#39;s page"><span>D&amp;G</span></a></li>'
  + '</ul></nav>';
equal(rendered, expected, 'exact deterministic escaped fragment');
equal(JSON.stringify(contacts), before, 'input not mutated');
equal(renderContactStrip('&amp;', []), '<nav aria-label="CONTACTS"><h1>&amp;amp;</h1><ul></ul></nav>', 'ampersand escaped once as input text');

throwsType(() => renderContactStrip('', []), 'empty title');
throwsType(() => renderContactStrip(' \t ', []), 'whitespace title');
for (const contact of [
  { label: ' ', address: '/x', glyph: 'x' },
  { label: 'x', address: '\n', glyph: 'x' },
  { label: 'x', address: '/x', glyph: '\t' },
]) {
  throwsType(() => renderContactStrip('Title', [contact]), 'blank contact field');
}

